style.css:
/* After Hours Arcade — roblox.com */

:root {
  /* swap these colors if you want */
  --my-bg: #171625;
  --my-surface: #242236;
  --my-surface-light: #302c45;
  --my-pink: #d9a9c7;
  --my-lavender: #b9aedf;
  --my-cream: #eee5df;
}

/* midnight background */
body {
  background: var(--my-bg) !important;
  color: var(--my-cream) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* dreamy links */
a {
  color: var(--my-lavender) !important;
  transition: color 0.2s ease !important;
}

a:hover {
  color: var(--my-pink) !important;
}

/* cozy buttons */
button {
  border-radius: 12px !important;
  transition: all 0.2s ease !important;
}

button:hover {
  filter: brightness(1.12) !important;
}

/* softer images */
img {
  border-radius: 10px;
}

/* gentle form elements */
input,
textarea {
  background: var(--my-surface) !important;
  color: var(--my-cream) !important;
  border: 1px solid var(--my-surface-light) !important;
  border-radius: 10px !important;
}
